def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the repeating color order from adjacent cells in the patterned area.
    freq = {}
    transitions = {}
    for r in range(3, h):
        for c in range(3, w):
            v = grid[r][c]
            if v:
                freq[v] = freq.get(v, 0) + 1
            if c + 1 < w and v and grid[r][c + 1]:
                nxt = grid[r][c + 1]
                transitions.setdefault(v, {})
                transitions[v][nxt] = transitions[v].get(nxt, 0) + 1

    # Ignore rare anomalous colors near the start of the pattern.
    colors = {v for v, n in freq.items() if n >= 4}
    succ = {}
    for v in colors:
        options = {u: n for u, n in transitions.get(v, {}).items() if u in colors}
        if options:
            succ[v] = max(options, key=options.get)

    start = max(colors, key=lambda v: freq[v])
    order = []
    v = start
    while v not in order and v in succ:
        order.append(v)
        v = succ[v]

    # In the unlikely event transitions do not form a full cycle, append leftovers.
    for v in sorted(colors):
        if v not in order:
            order.append(v)
    p = len(order)
    index = {v: i for i, v in enumerate(order)}

    out = [row[:] for row in grid]
    for r in range(h):
        if r < 3:
            for c in range(w):
                if grid[r][c] == 0:
                    out[r][c] = 1 if r < 2 or c < 2 else 4
            continue

        phases = []
        for c in range(3, w):
            value = grid[r][c]
            if value in index:
                phases.append((index[value] - c) % p)
        if phases:
            phase = max(set(phases), key=phases.count)
        else:
            phase = 0

        for c in range(w):
            if grid[r][c] != 0:
                continue
            if c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                out[r][c] = order[(c + phase) % p]

    return out
